-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx0e91d8816a2d$doc_civil_service_act_2049_1993__2049_civil_service_act_2049_pdf$CODEx0e91d8816a2d$,$CODEx67b918823a9e$Civil Service Act, 2049 (1993)$CODEx67b918823a9e$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2049,1993,91,$CODEx752272698716$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \n \n 1 \nwww.lawcommission.gov.np \nCivil Service Act, 2049 (1993) \n \nDate of Authentification and Publication  \n         2050.2.4 (17 May 1993)  \n \nAmendments \n:", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Nepal Health Services Act, 2053 (1997)  2053.11 .15", "content": "(February 16, 1997)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Civil Service (First Amendment) Act, 2055 (1998)  2055.3.29", "content": "(July 13, 1998)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Some Nepal Acts Amendments Act, 2057(2000) 2057 .4.26", "content": "(August 10, 2000)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Parliament Secretariat Act, 2058 (2001)  2058.8 .28", "content": "(December 13, 2001)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Civil Service (Second Amendment) Act, 2064 (200 7)  2064.4.23", "content": "(August 8, 2007) \nAct No. 2 of the year 2050 (1993) \nAn Act Made to Provide for the Constitution, Operat ion and \nConditions of Service of the Civil Service  \nPreamble : Whereas, it is expedient to make provisions on the  \nconstitution, operation and conditions of service o f the civil service in \norder to make the civil service more competent, vigo rous, service-oriented \nand responsible; \nNow, therefore, be it enacted by Parliament in the Twenty-second \nyear of the reign of His Majesty King Birendra Bir Bikram Shah Dev . \nwww.lawcommission.gov.np \n \n 2 \nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 1", "title": "Chapter 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title and Commencement :  (1) This Act may be called as", "content": "\"Civil Service Act, 2049 (1993)\".  \n(2) This Act shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions : In this Act, unless the subject or the context ot herwise", "content": "requires :- \n(a) \"Civil Service\" means the civil service constit uted pursuant to \nSection 3. \n(b) \"Civil Employee\" means any person who is holdin g a post of \nthe civil service. \n(c) \"Authority\" means any official with powers to m ake \nappointments pursuant to Section 9. \n(d) \"Family\" means the husband, wife, son, unmarrie d daughter, \nadopted son, unmarried adopted daughter, father, mo ther or \nstep mother living together with a Civil employee a nd whom \nhe/she himself/herself has to maintain and subsist,  and this \nterm also includes his/her grandfather, grandmother  in the \ncase of a \n/twoinvmale and unmarried female  employee , and her \nmother-in-law, father-in-law, in the case of marrie d female ● \nemployee. \n(e) \"Head of Department\" means the prescribed offic ial. \n(f) \"Head of Office\" means the head employee of the  prescribed \noffice. \n                                                   \n/twoinv  Amended by the Second Amendment. \n●  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 3 \nwww.lawcommission.gov.np \n(g) \"Permanent post\" means a post of the civil serv ice which is \npensionable and of which term is not specified. \n(h) \"Expert post\" means a post which has functions,  duties and \nresponsibilities of special nature and requires spe cial \nqualifications. \n●(h1)  \"Trade union of civil employees\" means the tr ade union of \nthe civil employees constituted pursuant to Sub-sec tion (1) of \nSection 53. \n●(h2) \"Authentic trade union of civil employees\" mea ns the \nauthentic trade union of the civil employees consti tuted \npursuant to Sub-section (3) of Section 53. \n(i) \"Prescribed\" or \"as prescribed\" means prescribe d or as \nprescribed in the rules framed under this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 2", "title": "Chapter 2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Constitution of Civil Service : Government of Nepal shall", "content": "constitute the civil services as follows:  \n                                                   \n●  Inserted by the Second Amendment. \n \n▲  Inserted by the First Amendment. \nwww.lawcommission.gov.np \n \n 4 \nwww.lawcommission.gov.np \n/oneinv(a) Nepal Economic Planning and Statistics Service;  \n(b) Nepal Engineering Service; \n(c) Nepal Agricultural Service; \n(d) Nepal Judicial Service; \n•(d1) Nepal Foreign Service; \n(e) Nepal Administration Service; \n•(e1) Nepal Audit Service; \n(f) Nepal Forestry Service; \n(g) Nepal Miscellaneous Service; \n(h) Nepal Education Service; \n (i) ♦----------------------- \n (j) ♥----------------------- \n/twoinv4. Class : (1) There shall be the following classes in the civ il service:  \n  Gazetted   Non-gazetted  \n  Special   First \n  First   Second \n  Second   Third \n  Third    Fourth \n      Fifth \n                                                   \n/oneinv  Amended by the First Amendment. \n] \n•  Inserted by the Second Amendment \n♦   Omitted by Parliament Secretariat Act, 2058(2001 ). \n♥  Omitted by Nepal Health Services Act, 2053 (1997) . \n/twoinv  Amended by the Second Amendment. \n \n \n \n \n \nwww.lawcommission.gov.np \n \n 5 \nwww.lawcommission.gov.np \n(2) If any employee working in the classless post i ntends to \nbe affiliated with the class at the time of commenc ement of this \nSection, the employee may be affiliated as prescrib ed with the Non-\ngazetted fifth class. \n•4A. Special provision relating to integrated civil service system : \nNotwithstanding anything contained in Section 4, th e Government \nof Nepal shall commence the integrated civil servic e system by \nconverting classes of the civil service into the la yer system from \nsuch date as may be appointed by a Notification in t he Nepal \nGazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Posts of Service : (1)There shall be technical and administrative", "content": "posts including the expert post in different classe s of the civil \nservice. \n(2) In addition to those mentioned in Sub-section ( 1), there \nmay also be classless posts, as prescribed, in the Civil service. \n(3) /scissorschilds--------- \n•5A. Job description : (1) Based on the job description of the \norganization approved by the Government of Nepal, t he concerned \nSecretary, Head of Department and Head of Office mu st prepare and \nenforce the job description of each civil post. Suc h job description \nmust clearly specify, inter alia,  the functions, duties, responsibilities \nand powers of such post and qualifications for the same. \n(2) In posting the civil employee to any post, the job \ndescription and the indicators for the evaluation o f functions as \nspecified in the job description must also be provi ded, along with \nthe posting letter. \n                                                   \n•  Inserted by the Second Amendment \n \n/scissorschilds  Omitted by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 6 \nwww.lawcommission.gov.np \n(3) Other provisions relating to the job descriptio n shall be as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Groups and sub-groups : (1) There may also be different groups", "content": "and sub-groups, as prescribed, in the civil service . \n▲ (la) Notwithstanding anything contained in Sub-sect ion (1), \nthere shall not be service, group or sub-group abov e the gazetted \nfirst class of other service, except in the post of  /twoinvNepal Judicial \nService and Nepal Audit Service . \n(2) The minimum qualifications required for differe nt posts in \nthe groups and sub-groups of different civil servic es shall be as \nprescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 3", "title": "Chapter 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "9", "title": "Appointment to the post of civil service :  (1) Government of", "content": "Nepal shall make appointment to the gazetted post o f the civil \nservice; and a Notification of such appointment sha ll be published in \nthe Nepal Gazette. \n(2) The Head of Department may make appointment to the \nnon- gazetted post of the civil service. \n(3) Notwithstanding anything contained in Sub-secti on (2), \nthe Head of Office may make appointment to the non- gazetted and \nclassless post in his/her office and subordinated o ffice. \n/oneinv/oneinv /oneinv/oneinv10. Disqualifications for being candidate : (1) The following \npersons shall not be qualified to be candidate for the post of the civil \nservice:  \n(a) In the case of non-gazetted and classless post,  \nthose who have not completed the age of \nEighteen years, \n(b) In the case of gazetted post, those who have no t \ncompleted the age of Twenty One years, \n(c) In the case of male and female candidates, thos e \nwho have already completed the age of Thirty \nFive years and that of Forty years, respectively, \n                                                   \n/scissorschilds  Omitted by the Second Amendment \n \n/oneinv  Amended by the First Amendment. \nwww.lawcommission.gov.np \n \n 15  \nwww.lawcommission.gov.np \n  Provided that, \n(1) Any person who has not crossed the age \nof Forty years may be a candidate for such \npost of the civil service /scissorschilds.......... as may \nbe specified for appointment of an ex-\narmy or police thereto. \n/twoinv(2) Any person who has not crossed the age \nof Forty Five years may be a candidate for \nthe open competition of gazetted second \nand first class.  \n(3) The age bar shall not be applicable in the \ncase of permanent incumbent employees \nof the civil service. \n(d) Those who have been dismissed from service, \nwith being disqualified for government service \nin the future, \n(e) Those who are non-Nepalese citizens, \n(f) Those who have been convicted by the court of a  \ncriminal offence involving moral turpitude. \n/twoinv(2) In the case of the female civil employee who ha s been \ntemporarily appointed to any post of development si de or \ndevelopment project of Government of Nepal and serv ing \ncontinuously since at least Five years ago, the age  bar shall not be \napplicable to her to become a candidate in the adve rtisement of the \nPublic Service Commission for open competition.  \n                                                   \n/scissorschilds  Deleted by the Second Amendment \n/twoinv  Amended by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 16  \nwww.lawcommission.gov.np \n/oneinv/oneinv /oneinv/oneinv11.  Provisions relating to temporary appointment : (1) The Public \nService Commission shall, for the purpose of making  temporary \nappointments, publish a separate list arranged in o rder of merit from \namongst those candidates who have attended the exam ination  \nconducted by it but have not been recommended for pe rmanent \nappointment. \n(2) If any temporary appointment is to be made to a ny vacant \npost of the civil service, the concerned Ministry m ust write to the \nPublic Service Commission. \n(3) The Public Service Commission shall, if so writ ten to it \npursuant to Sub-section (2), recommend the person in cluded in the \nlist arranged in order of merit for temporary appoi ntment on the \nbasis of the requisition of the concerned Ministry.  \n(4) The concerned Ministry shall temporarily appoin t the \nperson recommended pursuant to Sub-section (3) for a  period not \nexceeding six months. \n(5) The concerned Ministry must give information of  \ntemporary appointment made pursuant to Sub-section (4) to the \nMinistry of General Administration within seven day s. \n(6) If any one makes temporary appointment in contr avention \nof this Section, the salary, allowances and amounts  for other \nfacilities earned and received by the civil employe e so appointed \nshall be realized from the appointing office-bearer  as government \ndues.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Retention of lien : The civil employee shall continue to have lien", "content": "over his/her post in the following circumstances: \n(a) As long as he/she continues to function in that  post;  \n                                                   \n/oneinv  Amended by the First Amendment. \nwww.lawcommission.gov.np \n \n 17  \nwww.lawcommission.gov.np \n(b) Until the period of time allowed for the assump tion of charge \nof another post, on being transferred to that post;  \n(c) While he/she is on leave; \n(d) While he/she is under suspension; \n(e)  While he/she is deputed by Government of Nepal  on \ngovernmental or non-governmental business or while he/she \nis serving in any other post in an acting capacity.  \n/oneinv/oneinv /oneinv/oneinv13.  Acting assignment : /twoinv(1) If the post of any Head of Department or \nHead of Office falls vacant or the employee holding  such post goes \non leave for a period exceeding Fifteen days or bec omes subject to \naction pursuant to the prevailing law, a civil empl oyee of the same \ngrade or of one class lower post who has already be come a potential \ncandidate for promotion may be assigned to act in t hat post for a \nmaximum period of Six months, in order to perform t he functions of \nthat post for the time being. In cases where anyone  has been so \nassigned to act in any post, that person or any oth er person shall not \nbe again assigned to act in that post.  \n(2) If any employee is assigned as acting in contra vention of \nSub-section (1), the salary, allowances and amounts  for other \nfacilities earned and received by such employee dur ing his/her \nholding of that post shall be realized as governmen t dues from the \noffice-bearer assigning him/her as acting.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Oath : Each civil employee must, before assuming his/her o ffice", "content": "after being appointed for the first time, swear an oath as prescribed. \n                                                   \n/oneinv  Amended by the First Amendment. \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 18  \nwww.lawcommission.gov.np \n/twoinv15.  Posting of civil employee : (1) The posting of a civil employee \nshall be made based on his/her educational qualific ations, training \nand experience.  \nProvided that, the placement in the post of gazette d first class \nor the Head of Department shall be made with the co nsent of the \nMinistry of General Administration. In giving such consent for the \nplacement in such post, the Ministry of General Adm inistration \nshall, in coordination with the concerned Ministry,  give the consent \nfor the placement in the post from amongst the empl oyees who has \nleadership capacity, in addition to the said matter s. \n (2) In posting or transferring any civil employee to the \nprescribed Head of Department, Head of Office or an other post, \nGovernment of Nepal may make such posting or transf er after \nconcluding a job performance agreement with the con cerned office-\nbearer, subject to the job description correspondin g to the \nadministrative job nature of the functions attached  to that post. \n(3) In order to work along with the incumbent offic e-bearer \nholding the post of Secretary of special class of G overnment of \nNepal or post equivalent thereto and the post of He ad of Department \nof a central body and have hand-over and take-over of charge, a \nspecial post shall, ipso facto , be created for Fifteen days, and \nposting shall be made prior to the retirement of th e incumbent \noffice-bearer. \n(4) Other provisions relating to posting shall be a s prescribed.   \n/twoinv16. Probation period : While making fresh appointment to any \npermanent post of the civil service, such appointme nt shall be made \non probation for a period of Six months in the case  of a female civil \nemployee, and one year, in the case of a male civil  employee. If \n                                                   \n/twoinv  Amended by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 19  \nwww.lawcommission.gov.np \nhis/her performance is not satisfactory during the probation period, \nhis/her appointment may be canceled. The appointmen t of a civil \nemployee whose appointment has not been so cancelle d shall be \ndeemed to have ipso facto  been confirmed on the expiration of the \nprobation period.  \nProvided that, any employee who has already complet ed the \nprobation period upon being once appointed permanen tly to a post in \nthe civil service is appointed to another post and obtains the \ndispatch letters shall not be required to undergo t he probation period \nagain. \nExplanation : For the purposes of proviso (3) of Clause (c) of \nSub-section (1) of Section 10 and this Section, \"ci vil Service\" \nalso includes the Parliamentary Service and the Nep al Health \nService.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Tenure of Chief Secretary and Secretary : The tenure of the", "content": "Chief Secretary and the Secretary shall be three an d Five years, \nrespectively. \n* ------------- \nExplanation : For purposes of this Section, the term \n\"Secretary\" means a civil employee holding any post  of \nspecial class.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 4", "title": "Chapter 4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "20", "title": "Promotion committee : (1) There shall be a promotion committee", "content": "as follows to make recommendation for promotion to t he other \ngazetted post of the civil service, except for prom otion to the \n▲ gazetted  post of Nepal Judicial Service and for promotion f rom \nthe non-gazetted post to the gazetted post: \n(a) Chairperson of the Public Service \nCommission or Member of the Public \nService Commission designated by \nhim/her            - Chairperson \n(b) Member of the Public Service \nCommission designated by the \nChairperson of the Public Service \nCommission - Member \n(c) Chief Secretary - Member \n(d) Expert in the concerned subject \nnominated by the Public Service \nCommission - Member \n                                                   \n•  Inserted by the Second Amendment. \n▲   Inserted by the First Amendment. \nwww.lawcommission.gov.np \n \n 31  \nwww.lawcommission.gov.np \n(e) Secretary at the Ministry of General \nAdministration - Member secretary \n•(1a) There shall be a promotion committee as follow s, to \nmake recommendation for promotion to the gazetted th ird class from \nthe non-gazette first class: \n(a) Member of the Public Service \nCommission designated by the \nChairperson of the Public Service \nCommission -\n Chairperson \n(b) Secretary at the Public Service \nCommission -\n Member \n(c) Secretary at the Ministry of General \nAdministration -\n Member \n(d) Expert in the concerned subject \nnominated by the Chairperson of the \nPublic Service Commission -\n Member \n(e) Secretary at the Ministry relating to \nService, Group or Sub-group or \nGazetted First Class Officer designated \nby him/her -\n Member-Secretary \n•(1b) The secretariat of the promotion committee ref erred to \nin Sub-section (1a) shall be at the Ministry operat ing the service, \ngroup or sub-group . \n (2) There shall be a promotion committee, as presc ribed, to \nmake recommendation for promotion to the non-gazett ed post of the \ncivil service.  \n                                                   \n•  Inserted by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 32  \nwww.lawcommission.gov.np \n(3) The procedures to be followed by the promotion \ncommittee to make recommendation for promotion of t he civil \nemployees shall be as prescribed. \n/twoinv(4) The promotion committee must, while publishing a \npromotion name list, also publish the marks obtaine d by the \npotential candidates who have filled up the forms f or promotion. \n•(4a) The promotion committee shall publish the resu lts of \npromotion within four months from the last date of submission of \napplication forms. \n▲ (5) The promotion committee must prepare an annual plan \nof operations and carry out its functions as per th at plan. \n▲ 20A.Special provisions relating to promotion : (1) Notwithstanding \nanything contained elsewhere in this Act, if any ci vil employee of \nthe gazetted /twoinvfirst  class or below than that holding the same post for  \nat least Fifteen years has One month left to get re tirement pursuant \nto Section 33, such employee shall be promoted to o ne /twoinvclass  higher \npost.  \n(2) Notwithstanding anything contained elsewhere in  this Act, \nif any civil employee of the gazetted /twoinvfirst  class or below than that \nholding the same post for at least Fifteen years in tends to have \nvoluntary retirement pursuant to Section 35 and mak es an \napplication therefor, such employee shall be grante d retirement by \npromoting him/her to One /twoinvclass  higher post. \n(3) A special post shall ipso facto  be created to make \npromotion pursuant to Sub-section (1) or (2) and th at post shall ipso \n                                                   \n/twoinv  Amended by the Second Amendment. \n \n▲   Inserted by the First Amendment. \n \n \n  \n \n \n \n \n \nwww.lawcommission.gov.np \n \n 33  \nwww.lawcommission.gov.np \nfacto  lapse upon the retirement of such a civil employee  from \nservice. \n•(4) Notwithstanding anything contained elsewhere in  this \nSection, an employee who dies after the completing the period as \nreferred to in this Section in the same post, the p ension and other \nfacilities payable to one level higher post shall b e provided to the \nfamily of such an employee. \n•(5) Notwithstanding anything contained elsewhere in  this \nSection, any employees of gazetted first and second  class holding \nthe same post for at least fifteen years wish to ta ke retirement with \npromotion, such employees shall be granted retireme nt by \npromoting them to one class higher post. \n/oneinv/oneinv /oneinv/oneinv21. Minimum service period and educational qualific ations \nrequired to be candidate for promotion : /twoinv (1) In order to be a \ncandidate for promotion, one must possess the educa tional \nqualifications as prescribed for the post that is O ne class below the \nclass of the post to which promotion is made and ha ve completed \nthe minimum service period as follows: \n(a)  Three years for a non-gazetted post,  \n(b) Five years for a gazetted post. \n(2) Notwithstanding anything contained in Sub-secti on (1), \neven though any •women, Adiwasi/Janjati, Madhesi, Dalit , Disable \nand permanently residing in the backward area  civil employee has a \nservice period that is the above-mentioned service period less one \nyear, she shall be a potential candidate for promot ion. \n                                                   \n•  Inserted by the Second Amendment \n/oneinv  Amended by the First Amendment \n/twoinv  Amended by the Second Amendment. \n \n  \n \n \n \nwww.lawcommission.gov.np \n \n 34  \nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Ineligibility for being potential candidate for  promotion :", "content": "Notwithstanding anything contained in Section 21, a  civil employee \nshall not be eligible to be a potential candidate f or promotion in the \nfollowing circumstances and during the following pe riod:  \n(a) In the event of suspension, during the period o f suspension, \n(b) In the event of withholding of promotion, durin g the period of \nwithholding, \n(c)  In the event of withholding of increment in sa lary, during the \nperiod of withholding, \n•(d) During the period of five years after the date of change in the \nservice or group in the case of an employee who has  so \nchanged the service or group pursuant to Section 26  and after \nthe change in the service or group in the case of a n employee \nwho has got such a change upon an application made by \nhimself/herself.  \n▲ 22A. Withholding and sanction of promotional appoin tment : If \nany civil employee is suspended or his/her appointm ent or salary \nincrement is withheld after he/she has been recomme nded for \npromotion but before he/she gets promotional appoin tment, his/her \npromotional appointment shall then be withheld duri ng the said \nperiod; and in the event of his/her acquittal of th e suspension or \nafter the expire of the period of withholding, he/s he shall be granted \nappointment and only seniority shall be maintained as if he/she were \nnot suspended or his/her promotion or salary increm ent were not \nwithheld.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "♣… … … …", "content": "•  Inserted by the second Amendment. \n▲   Inserted by the First Amendment . \n♣  Repealed by the First Amendment. \nwww.lawcommission.gov.np \n \n 35  \nwww.lawcommission.gov.np \n/twoinv24. Criteria for promotion on ground of work effici ency : (1) The \npromotion committee shall recommend a civil employe e for \npromotion based on the total marks secured for the work efficiency. \n(2) In evaluating the work efficiency of the civil employee, a \nmaximum of 100 marks shall be granted as follows: \n(a) For work performance evaluation -Forty marks \n(b) For seniority - Thirty marks \n(c) For educational qualifications - Twelve marks \n(d) For service in geographical \nregion \n-Sixteen marks \n(e) For training - Two marks \n(3) In calculating the marks for the work performanc e \nevaluation of a potential candidate, the marks shal l be calculated \nbased on the last day of Ashad , and in calculating the other marks, \nthe marks secured by the deadline for making applic ation for \npromotion shall be calculated. \n▲\n24A.  Evaluation of work performance : (1) The work performance \nevaluation form as prescribed shall be used to eval uate the work \nperformance of civil employee. \n(2) The distribution of the total marks for the wor k \nperformance evaluation of civil employee shall be a s follows: \n(a) Maximum marks that may be  \ngranted by the supervisor \n-Twenty  \nfive \n                                                   \n/twoinv  Amended by the Second Amendment. \n \n▲   Inserted by the First Amendment . \nwww.lawcommission.gov.np \n \n 36  \nwww.lawcommission.gov.np \nmarks \n(b)  Maximum marks that may be  \ngranted by the reviewer \n-Ten \nmarks \n(c) Maximum marks that may be  \ngranted by the review committee \n-Five \nmarks \n(3) The supervisor, reviewer and review committee m ust, \nwhile granting marks for the work performance of a c ivil employee, \ngrant marks in accord with the criteria mentioned i n this Section and \nin the work performance evaluation form. \n/twoinv(4) The work performance evaluation of the gazetted civil \nemployee shall be carried out on a semi-annual (hal f yearly) and \nannual basis and that of the non-gazetted employee on an annual \nbasis. \n/twoinv(5) In carrying out the work performance evaluation  on a \nsemi-annual basis pursuant to Sub-section (4), the concerned \ngazetted employee must fill up the form in duplicat e in the \nprescribed format, indicating the specified functio ns, discharged \nfunctions, functions which could not be completed a nd reasons for \nthe same and submit it to the supervisor within Sev en days after the \nexpiry of that period. The supervisor must evaluate  the form so \nsubmitted, mention feedbacks to be provided in the specified space \nof the form and return a copy to the concerned empl oyee within \nanother Seven days. The annual work performance eva luation form \nmust be evaluated based on every work performance e valuation \nform filled up on a semi-annual basis. The Authorit y may take \ndepartmental action against the employee who fails to fill up the \n                                                   \n/twoinv  Amended by the Second Amendment. \n \n \n \nwww.lawcommission.gov.np \n \n 37  \nwww.lawcommission.gov.np \nsemi-annual work performance evaluation form in the  specified time \nand against the supervisor who fails to examine it and provide \nfeedbacks.  \n/twoinv(6) In respect of the work performance evaluation t o be \ncarried out on an annual basis, the concerned Head of Office and \nHead of Department must, in the case of the non-gaze tted and \nclassless employee, carry out or cause to be carrie d out evaluation \nwithin the specified period, prepare it in triplica te, send a copy each \nto the Public Service Commission and the promotion committee \nsecretariat and retain the other copy in the concer ned office. In the \ncase of gazetted civil employee, the Secretary at t he concerned \nMinistry, Secretariat, Commission or central body m ust carry out, or \ncause to be carried out, evaluation within the spec ified period, \nprepare it in triplicate, send a copy each to the P ublic Service \nCommission and the promotion committee secretariat and retain the \nother copy in the concerned Ministry, Secretariat, Commission or \ncentral body. Each body carrying out work performan ce evaluation \nmust publish a notice, also containing a name list sent to the body to \nwhich it has to submit the form evaluated by it wit hin the prescribed \nperiod, on the notice board of its office within se ven days. \n•(6a) Each civil employee must fill up his/her work \nperformance evaluation form and register it with th e concerned \noffice within the prescribed period of time. If the  concerned \nemployee fails to register it within such period of  time and makes an \napplication, accompanied by reasonable reasons ther efor, for the \nextension of time limit, the supervisor may, if he/ she thinks the \nreasons mentioned in the application to be reasonab le, extend the \ntime limit for a period not exceeding fifteen days after the date of \n                                                   \n/twoinv  Amended by the Second Amendment. \n \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 38  \nwww.lawcommission.gov.np \nexpiry of the prescribed period of time. The promot ion committee \nshall subtract one mark from the total marks for th e work \nperformance evaluation form registered within the e xtension time of \nthat fiscal year. \nProvided that, if any employee has to go for a fore ign \ntraining, workshop or study tour during the period of filling up the \nwork performance evaluation form, the employee has to fill up the \nwork performance evaluation form  and register it w ith the \nconcerned office prior to make such departure. The work \nperformance evaluation form so registered shall be evaluated as if it \nwere registered with the specified time. \n•(6b) Departmental action shall be taken against the  office-\nbearer who does not evaluate, within the prescribed  period of time, \nthe work performance evaluation form filled and reg istered by the \ncivil employee in time. \n•(6c) If, after the review committee has carried out  the annual \nwork performance evaluation to be carried out each year, the \nconcerned employee makes an application for informa tion of the \ntotal marks of work performance evaluation that he/ she has secured \nin that year, the review committee secretariat must  give such \ninformation. \nProvided that, information of the marks given by th e review \ncommittee shall not be given. \n•(6d) After receiving information pursuant to Sub-se ction \n(6c), if any employee is not satisfied with the eva luation made by \nthe supervisor or reviewer may make a complaint, ac companied by \nthe solid ground and reason for such dissatisfactio n, to the \n                                                   \n \n \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 39  \nwww.lawcommission.gov.np \nprescribed authority within seven days. Where a com plaint is so \nmade, such authority shall conduct necessary invest igation, in \nconsultation with the concerned supervisor and revi ewer, and may, \nif so required, amend, as prescribed, the marks obta ined in such an \nevaluation form.   \n(7) If the supervisor or the reviewer grants more t han Ninety \nFive per cent or less than Seventy Five per cent ma rks for the work \nperformance evaluation to be carried out annually, he/she must set \nout clear reasons therefor; and where he/she grants  less than Seventy \nFive per cent marks, he/she must inform the concern ed employee \nthereof and submit it to the review committee, alon g with the \nreactions, if any, made by such employee. The revie w committee \nmay, if it is not satisfied with the evaluation of the work \nperformance carried out by the supervisor or the re viewer or by \nboth, return it, also setting out the clear reasons  therefor. In cases \nwhere it is so returned, the concerned evaluator mu st reevaluate it or \nset out justifiable reasons why it is not necessary  to amend the \nevaluation carried out previously and forward it ac cordingly. \n(8) While calculating marks for purposes of work \nperformance evaluation, the marks shall be calculat ed on the basis \nof the average figure of the work performance evalu ation form of \nsuch last year as the service for which is required  to become a \npotential candidate for promotion. \nProvided that: \n/twoinv(1)  Marks due for the work performance evaluation \nfor the period of training and study undergone or \nof the period of suspension where the suspension \nof an employee has been released shall be \ngranted in proportion of the marks secured in the \n                                                   \n/twoinv  Amended by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 40  \nwww.lawcommission.gov.np \nyear immediately preceding the departure for \nsuch study or training or preceding such \nsuspension. \n/twoinv(2) The potential candidacy shall be calculated onl y \nby deducting the period of extra-ordinary leave \nundergone; and the work performance evaluation \nform shall not be filled up for the period of such \nleave. The work performance evaluation of the \nsubsequent period shall be calculated after \ndeducting the period of extra-ordinary leave \nundergone, for the service period of such years \nas required to be a potential candidate for \npromotion. \n(9) /scissorschilds----------------- \n(10) Other provisions relating to the work performa nce \nevaluation shall be as prescribed. \n/twoinv24B. Evaluation of seniority : While granting to the civil employee \nmarks for seniority, a maximum of thirty marks shall  be granted as \nfollows:  \n(a)  At the rate of 3.75 marks for each year of ser vice in the post \nof non-gazetted third and second class, \n(b) At the rate of 3 marks for each year of service  in the post of \nnon-gazetted first class, \n(c) At the rate of 2.5 marks for each year of servi ce in the post of \ngazetted third and second class. \nProvided that- \n                                                   \n \n/scissorschilds  Deleted by the Second Amendment . \n \nwww.lawcommission.gov.np \n \n 41  \nwww.lawcommission.gov.np \n(1) While calculating marks for seniority, marks \nshall be calculated on a proportional basis for a \nperiod of more than One year by a few months \nor days. \n(2) For purposes of this Clause, no marks shall be \ngranted for the period of absence or extra-\nordinary leave undergone. \n/twoinv24C. Categorization of geographical regions : (1) While granting \nmarks to the civil employee for his/her experience of work in \ndifferent geographical regions, the different geogr aphical regions of \nthe country shall be classified into four categorie s viz. 'a', 'b', 'c' and \n'd', respectively, and marks shall be granted as fo llows not in excess \nof Sixteen marks for the work experience in one or more categories \nthereof: \n(a) For the post of non-gazetted third and second \nclass- \n (1) At the rate of 4 marks for each year of \nservice in category 'a', \n(2) At the rate of 3.25 marks for each year of \nservice in category 'b', \n(3) At the rate of 2.50 marks for each year of \nservice in category 'c', \n(4) At the rate of 2 mark for each year of \nservice in category 'd'. \n(b) For the post of non gazetted first class- \n (1) At the rate of 4 marks for each year of \nservice in category 'a', \n                                                   \n/twoinv  Amended by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 42  \nwww.lawcommission.gov.np \n(2) At the rate of 3.25 marks for each year of \nservice in category 'b', \n(3) At the rate of 2.50 marks for each year of \nservice in category 'c', \n(4) At the rate of 1.50 mark for each year of \nservice in category 'd'. \n(c) For the post of gazetted third and second class - \n (1) At the rate of 4 marks for each year of \nservice in category 'a', \n(2) At the rate of 3.25 marks for each year of \nservice in category 'b', \n(3) At the rate of 2.50 marks for each year of \nservice in category 'c', \n(4) At the rate of 1.25 mark for each year of \nservice in category 'd'. \n(2) Notwithstanding anything contained in Sub-secti on (1), \nthe marks already secured by any civil employee for  geographical \nregion at the time of commencement of this Section shall not \ndecrease. \n(3) For purposes of Sub-section (1), the descriptio n of \ndifferent geographical regions shall be as prescrib ed. \n(4) No marks of any one geographical region shall b e granted \nunless and until any employee makes continuous offi ce attendance \nfor at least Two Hundred Thirty Three days in that region. For a \nperiod more than Two Hundred Thirty Three days, mar ks of the \nsame geographical region shall be granted pro rata;  and marks \nequivalent to that of category 'd' shall be granted  for a period less \nthan that irrespective of the geographical region w here the employee \nwww.lawcommission.gov.np \n \n 43  \nwww.lawcommission.gov.np \nhas served.  The marks obtainable for the service i n geographical \nregion shall be calculated only if the marks have b een obtained in \nthe post that is one class lower than the class to which promotion is \nto be made. \n(5) The marks equivalent to that of category 'd' sh all be \ngranted to the civil employee who serves in a Nepal ese Diplomatic \nMission or any other office situated aboard and who  goes on \ndeputation for a study leave or  foreign training. \n▲ 24D.Evaluation of educational qualifications and tr aining : /twoinv(1) \nWhile granting marks to the civil employees for edu cational \nqualifications, a lump sum of twelve marks shall be  granted for the \nminimum educational qualifications required to join  any post of the \ncivil service and additional educational degree, wh ich is higher than \nthe minimum educational qualifications and in a sub ject related with \nthe service, group or sub-group. Both marks shall b e granted even if \nthe employee has obtained only the education qualif ication that is \nhigher then the minimum required educational qualif ication.  \n \nNumber \n \nEducational Qualification (Title) \nFirst \nclass \nSecond \nclass \nThird \nclass \n(a) For the Minimum educational \nqualification as required for the \nentry of service \n9 8.75 8.50 \n(b) For the any one additional \neducational qualification or the \n3 2.75 2.50 \n                                                   \n▲   Inserted by the First Amendment. \n/twoinv  Amended by the Second Amendment. \n \nwww.lawcommission.gov.np \n \n 44  \nwww.lawcommission.gov.np \nconcerned subject higher than \nthe minimum educational \nqualification for the entry into \nservice. \n(2)  \n/scissorschilds ---------- \n/twoinv(3) Except the minimum educational qualification pr escribed \nfor the posts of the gazette second and first class es, to be filled up \nthrough open competition pursuant to Clauses (f) an d (g) of Sub-\nsection (1) of Section 7, the minimum educational q ualification \nprescribed for the entry into the gazette third cla ss service shall be \ndeemed to be the minimum educational qualification also for the \npromotion to the posts higher than gazetted second class.  \n (4) /scissorschilds----------  \n/twoinv(5) For the in-service training, 2 marks, 1.75 mark s and 1.5 \nmarks shall be granted for the first, second and th ird division, \nrespectively. \n(6) While granting marks to the civil employee for training, \nmarks shall be granted for an in-service training o f a period of one \nmonth or more, in a subject related with the servic e. In calculating \nmarks for the training, the marks shall be calculat ed only for that \nclass while in which class he/she has been nominate d for the \ntraining. \n•Explanation : One month training shall mean a training of a \nperiod of thirty working days or more. \n                                                   \n/scissorschilds  Deleted by the Second Amendment. \n/twoinv  Amended by the Second Amendment. \n  \n•  Inserted by the Second Amendment.  \n \nwww.lawcommission.gov.np \n \n 45  \nwww.lawcommission.gov.np \n(7) The civil employee shall submit certified copie s of the \neducational qualifications and the in-service train ing. No marks \nshall be granted therefor if he/she fails to submit  them. \n•(8) Whether the educational qualification submitted  by a \ncivil employee along with the application for the p urpose of \npromotion is related with the service, group and su b-group or not \nshall be as decided by the equivalency determinatio n committee as \nprescribed. If the equivalency of the educational q ualification \nsubmitted along with the application for the purpos e of promotion is \nmade prior to a date before the holding of the meet ing of the \npromotion committee, the marks of such educational qualification \nshall be counted for promotion. \n•(9) Provisions relating to training institutions an d training \nstandards shall be as prescribed by Ministry of Gen eral \nAdministration, in coordination with the Ministry o perating the \nservice, group and sub-group. \n•24D1.Special provision of promotion by evaluation o f work \nperformance and experience : (1) Notwithstanding anything \ncontained elsewhere in this Act, the civil employee  shall be \npromoted up to one class, upon having completed the  following \nservice period in the following class, and obtained  the above \neducational qualification than prescribed education al qualification at \nthe earlier time of entry or group division or afte r the entry or group \ndivision:  \n(a) Non-gazetted Second Class -\n Ten years \n(b) Non-gazetted First Class -  Twelve years \n                                                   \n•  Inserted by the Second Amendment.  \n \n \nwww.lawcommission.gov.np \n \n 46  \nwww.lawcommission.gov.np \n(c) Gazetted Third Class -  Fifteen years \n(d) Gazetted Second Class -  Eighteen years \n(2) Notwithstanding anything contained in Sub-secti on (1) , \nthose civil employees shall be promoted up to one c lass upon having \ncompleted the service period of Eighteen, Fifteen a nd Thirteen years \nor more in the permanent post of the same class of gazetted third \nclass, non-gazetted second class and having the edu cational \nqualification and obtained the minimum educational qualification of \nthe prescribed subject at the time of entry of serv ice or group \ndivision of the concerned service, group or sub-gro up. \n(3) The following conditions shall have to be fulfi lled for the \npromotion pursuant to sub-sections (1) and (2) \n(a) Not being subject to action pursuant to Section  \n22; \n(b) Having obtained the marks average of ninety \npercent or more in the performance education of \nlast three years.  \n(4) There shall be a promotion committee as follows  to make \nrecommendation for promotion pursuant to sub-section s (1)  and (2) \nexcept the post of gazetted post of Nepal Judicial Service, and the \npromotion of gazetted post of Nepal Judicial Servic e shall be \nconducted by the Judicial Commission. \n(a) Member of the Public \nService Commis \nsion  \ndesignated by the \nchairperson of the Public \nService Commission -\n Chairperson \nwww.lawcommission.gov.np \n \n 47  \nwww.lawcommission.gov.np \n(b) Secretary at the Ministry or \nInstitution where the \nemployee is working -\n Member \n(c) Secretary at the Ministry of \nGeneral Administration or \ngazetted first class officer of \nthe ministry designated by \nhim/her -\n Member \nExplanation : The Secretary of the Office of the Prime \nMinister and Council of Ministers will be the membe r in a \ncondition of the promotion of the employee of Minis try of \nGeneral Administration. \n(5) The promotion Committee Secretariat pursuant to  Sub-\nsection (4) shall be at the Ministry or Institution  where the employee \nworked as candidate for the promotion. \n(6) The special post of concerned service, group, s ub-group of \nabove class ipso facto  at the employee working office for the \npromotion pursuant to Sub-section (1) or (2) and th e Civil Employee \nRecord Office shall register of such post from the date of the \ncommencement of promotion after the concerned insti tution provide \npromotion. \n(7) The position shall ipso facto  lapse if the employee is \npromoted, pursuant to Sub-section (6), gets retirem ent by any reason \nor is promoted to above post or adjusted to the reg istered post and \nthe post shall ipso facto  be settled as the earlier post before the post \nof his/her promotion, and the Civil Employees Recor d Office shall \nmaintain the records of such post accordingly. \n(8) The civil employee promoted for the special pos t pursuant \nto Sub-section (6) shall have to conduct work of th e post where \nwww.lawcommission.gov.np \n \n 48  \nwww.lawcommission.gov.np \nhe/she work before the promotion except in the case  of adjustment \npursuant to Sub-section (7). \nProvided that, the seniority of the employee promot ed as per \nthis Section shall be counted as promoted post and shall eligible for \nthe competition of the above post of above class th en promoted \nclass. \n(9) The transfer of the employee promoted as per th is Section \nshall be with the special post created as per the p romotion of this \nSection of other institution until the adjustment p ursuant to Sub-\nsection (7). \n(10) Notwithstanding anything contained elsewhere i n this \nAct, in cases where the employee of the same class of one office \npromoted as per this Section and might be the offic e chief post, the \nsenior employee among such class employee worked as  office chief. \n(11) Notwithstanding anything contained elsewhere i n this \nAct, the promotion proceeding work performance eval uation shall be \nconducted before and then after the recommendation of promotion \naccording to this Section the conduced except the f irst time of the \ncommencement of this Act. \n(12) Notwithstanding contained anything elsewhere i n this \nSection, the promotion provision of this Section sh all not commence \nfor the layer increase. \n(13) Notwithstanding any thing contained elsewhere in this \nSection, no adverse effect shall be made to the pro vision of open \ncompetition by promotion pursuant to this Section. \n(14) The procedures for inviting applications for p romotion \nby evaluation of work performance and experience, r esult \npublication and duration, claim of promotion and ad justment of \nwww.lawcommission.gov.np \n \n 49  \nwww.lawcommission.gov.np \npromoted employees and other relevant provisions sh all be as \nprescribed.  \n•24D2.Provision relating to layer upgrade of classle ss employee : \n(1) The layer of the classless post shall be as fol lows: \n(a) First layer, \n(b) Second layer, \n(c) Third layer, \n(d) Fourth layer, \n(e) Fifth layer. \n(2) The employee who is firstly appointed to the cl assless \npost shall be maintained into the first layer. \n(3) The competent authority shall upgrade as follow s the \nclassless employees whose records of punishment hav e not been \nmaintained pursuant to Section 18E. \n(a) Second layer having the service period of Five \nyear or more and less than Ten years. \n(b)  Third layer having the service period of Ten \nyear or more and less than Fifteen years. \n(c) Fourth layer having the service period of Fifte en \nyear or more and less than Twenty years. \n(d) Fifth layer having the service period of Twenty  \nyear or more. \n(4) The pay scale of the layer pursuant to Sub-sect ion (3) \nshall be as prescribed by the Government of Nepal. \n(5) The other provisions relating to upgradation sh all be as \nprescribed.  \n                                                   \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 50  \nwww.lawcommission.gov.np \n/twoinv/twoinv /twoinv/twoinv24E. Sheet roll/personal details to be maintained : (1) It shall be the \nresponsibility of the concerned Head of Department or Head of \nOffice to maintain accurately the sheet roll/person al details of the \ncivil employee serving in his/her office. It shall be the obligation of \nthe concerned employee to update, or cause to be up dated, his/her \nsheet roll/personal details.  \n(2) If the civil employee who has already been a po tential \ncandidate for promotion fails to submit the applica tion form because \nof his/her staying abroad in the course of a govern mental business or \nstudy or deputation or occurrence of a natural cala mity or \ncircumstance beyond control, the concerned Head of Department or \nHead of Office must forward the details of such emp loyee to the \noffice publishing a notice for promotion, within th e time-limit of the \nnotice for promotion. The promotion committee shall  settle acts of \npromotion based on the details so forwarded. \n(3) If it is proved that any candidate has mentione d false \ndetails in the promotion application form, departme ntal action shall \nbe taken against such candidate. \n▲ 24F. Complaint on promotion :  (1) The concerned civil employee, \nwho is not satisfied with the promotion recommendat ion made by \nthe promotion committee pursuant to Section 20, may  file a \ncomplaint with the Public Service Commission within  Thirty Five \ndays from the date of such recommendation; and the complaint so \nfiled shall be settled within Sixty days after the date of expiry of the \ntime limit for filing complaint.  \n(2) If, following the settlement of a complaint fil ed pursuant \nto Sub-section (1), the promotion name-list previou sly published is \n                                                   \n/twoinv  Amended by the Second Amendment. \n▲   Inserted by the First Amendment.  \nwww.lawcommission.gov.np \n \n 51  \nwww.lawcommission.gov.np \nto be amended, the complaint hearing official shall  give a notice \nthereof to the promotion committee. \n(3) If, while examining a complaint pursuant to Sub -section \n(1), it appears that erroneous evaluation has been carried out \nknowingly, the Public Service Commission may warn t he evaluator. \n(4) If a complaint filed pursuant to Sub-section (1 ) is held to \nbe false, two marks and three marks of such a compl ainant shall be \ndeducted on the promotion to be made following the complaint, for \nthe complaint made for the first and second time, r espectively. \n(5) A notice of the action taken pursuant to Sub-se ction (3) or \n(4) must be given to the promotion committee secret ariat, the office \nwhere the concerned employee is in service and to t he concerned \nemployee, as well. \n(6) Other provisions on complaint on promotion shal l be as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Alteration in conditions of promotion : In making any", "content": "amendment to Sections 21, 22, /oneinv24, 24A, 24B, 24C and 24D  or the \nRules framed thereunder, provision shall be made so  that such \namendment shall come into force only on a date afte r One year of \nsuch amendment.  \n/twoinv/twoinv /twoinv/twoinv26. Change of service, group or sub-group : If, Government of \nNepal requires an employee with any special qualifi cations in any \nclass of any service, group or sub-group of the civ il service, and \ngiven that the post cannot be fulfilled by transfer  or promotion made \nwithin that service, group or sub-group, the post h as to be fulfilled \nby making a change in service from another civil se rvice, group or \nsub-group, Government of Nepal may change the servi ce, group or \n                                                   \n/oneinv  Amended by the First Amendment \n/twoinv  Amended by the Second Amendment . \nwww.lawcommission.gov.np \n \n 52  \nwww.lawcommission.gov.np \nsub-group of the employee selected through a compet itive \nexamination among the civil employees of the same c lass, having \npossessed the qualifications specified in an advert isement done by \nthe Public Service Commission on request of Governm ent of Nepal.  \nProvided that, in cases where the position is cut o ff because \nany civil service post of any body of the Governmen t of Nepal has \nbeen redundant and the employee in service in such position has to \nbe transferred to another service, group or sub-gro up given that the \npost of the service, group, sub-group and class so cut off is not \nvacant in any other body nor does such post fall va cant even until \nOne year, nothing contained in this Section shall b e deemed to \nprevent Government of Nepal from grouping into anot her service, \ngroup or sub-group, in consultation with the Public  Service \nCommission.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 5", "title": "Chapter 5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "27", "title": "Salary and allowance : (1) A civil employee shall be entitled to", "content": "salary and allowance from the day of assumption of his/her post. \n•(1a) There shall be a salary and allowance review \ncommittee as follows, so as to review the salary, a llowance and \nother facilities of the civil employee: \n(a) Chief Secretary of the \nGovernment  of Nepal \n \n-Chairperson \n(b) Secretary, Ministry of Finance -Member \n(c) Secretary Ministry of General  \n                                                   \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 53  \nwww.lawcommission.gov.np \nAdministration -Member \n•(1b) The salary and allowance review committee shal l, each \nyear, recommend to the Government of Nepal a dear al lowance \nbased on the consumer price index. The committee sh all, in every \nthree years, review the salary, allowance and other  facilities, based \non, inter alia , the revenue increase rate, total number of positi ons \nand the dear allowance provided based on the price index in the last \nthree years. The committee may set other procedures on its own.  \n•(1c) The committee referred to in Sub-section (1a) may \nconstitute a sub-committee as per necessity and may  invite any \nconcerned area expert and stakeholder to attend its  meeting for \nsuggestion. \n•(1d) The secretariat function pursuant to Sub-secti on (1a) \nshall be carried out by the Ministry of General Adm inistration. \n/twoinv/twoinv /twoinv/twoinv(2) The Government of Nepal shall, also based on th e \nrecommendation referred to in Sub-section (1a), each  year provide \nthe civil employee with an allowance in a sum not e xceeding \nSeventy Five percent of the consumer price index in creasing each \nyear. In a year where the allowance so provided is in excess of \nTwenty Five percent or more of the basic pay scale,  Twenty Five \npercent amount shall be adjusted in the salary scal e and the rest \namount provided as an allowance. \n/oneinv(3) Except in the circumstances stipulated in Secti on 29 or \n60, after the commencement of this Act, each civil e mployee shall \n                                                   \n \n•  Inserted by the Second Amendment. \n/twoinv  Amended by the Second Amendment. \n/oneinv  Amended by the First Amendment. \n \n \n \n \n \nwww.lawcommission.gov.np \n \n 54  \nwww.lawcommission.gov.np \nbe entitled to an increment in salary /handptrt1as prescribed, upon \ncompletion of one year of service. In so prescribin g the increment in \nsalary, the number of increment in salary shall be adjusted in a \nmanner that is not less than the amount being recei ved by the \nemployee . In the event of withholding of increment in salar y of any \ncivil employee, the concerned official must mention  in writing on \nwhich date the increment in salary is to be sanctio ned.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Entitlement to earned salary and allowance : (1) Each civil", "content": "employee shall receive salary /oneinvand allowance as well, if any \nreceivable , after completion of each month.  \n(2) Each civil employee shall receive his/her earne d salary \n/oneinvand allowance as well, if any receivable , even if he/she is relieved \nof the civil service for any reason whatsoever. \n(3) Except as provided in this Act or the Rules fra med \nhereunder, no salary of any civil employee shall be  deducted. \n(4) The salary to which any civil employee is entit led shall \nnot be withheld during the period he/she is serving  or is on leave. \n•28A. Work performance incentive fund : (1) Government of Nepal \nmay provide for a work performance incentive fund i n order to \nencourage the civil employee based on work performa nce, work \nresults and achieved results.  \n(2) The operation, management and other provisions of the \nfund as referred to in Sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Crossing of efficiency bar : No civil employee shall be deemed to", "content": "have crossed the efficiency bar until the Secretary  at the concerned \nMinistry, in the case of a gazetted employee, and t he Authority, in \n                                                   \n/handptrt1  Amended by Some Nepal Acts Amendment Act, 2057(20 00). \n/oneinv  Amended by the First Amendment \n \n \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 55  \nwww.lawcommission.gov.np \nthe case of a non-gazetted employee, mention in wri ting that such \ncivil employee is eligible to cross the efficiency bar.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Salary receivable in the event of suspension : (1) If any civil", "content": "employee is suspended in connection with any govern mental \nbusiness or as a result of an action taken on behal f of Government of \nNepal, such employee shall receive only half of his /her salary during \nthe period of such suspension. \nProvided that, if the charge against him/her is not  proved and \nhe/she is acquitted of the charge, he/she shall rec eive the salary less \nthe half salary, if any, he/she has received during  the period of \nsuspension and the full salary (including increment  in salary, if any, \nto be made) if he/she has not received the half sal ary. If he/she is \nconvicted, he/she shall not be entitled to the rema ining salary and \nallowances after the date of such suspension.  \n(2) If any civil employee is suspended for any reas on other \nthan that mentioned in Sub-section (1), he/she shal l not be entitled \nto any salary during the period of such suspension.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Deposit of contribution to Employee Provident F und : An", "content": "amount at the rate of Ten per cent of the monthly s alary of the civil \nemployee shall be deducted, and Government of Nepal  shall, adding \nthe amount of One Hundred percent thereof to such a mount, deposit \nthe total amount in the Employee Provident Fund.  \n/twoinv/twoinv /twoinv/twoinv32. Festival expenses and other facilities : (1)A civil employee shall \nreceive an amount equivalent to the salary of one m onth being \nearned by him/her as the festival expenses each yea r to celebrate \nfestival as per his/her religion, culture and custo m.  \n                                                   \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 56  \nwww.lawcommission.gov.np \n(2) An employee who has got retired with entitlemen t to \npension shall be provided with a sum equivalent to the pension of \nOne month payable to him/her, as the festival expen ses. \n(3) The provisions relating to medical expenses, di sability \npension, facilities payable on grounds of deformiti es, extra-ordinary \nfamily pension and gratuity, educational allowances , pension, child \ncare allowances to the offspring or other facilitie s shall be as \nprescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 6", "title": "Chapter 6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "33", "title": "Compulsory retirement : /oneinv(1) Any civil employee who has", "content": "completed the age of fifty-eight years or completed  the tenure as \nreferred to in Section 17 shall ipso facto  retire from the civil service. \n/oneinv(2) Even the civil employees who are incumbent in t he civil \nservice on the extension of their tenure after comp letion of the \nthirty-year service period, prior to the commenceme nt of Sub-\nsection (1), may hold office in the civil service u ntil they complete \nthe age of Fifty Eight years. \nProvided that, in the case of the employees whose t enure of \nservice is specified pursuant to Section 17, that S ection shall be \napplicable. \n/twoinv/twoinv /twoinv/twoinv(3) For purposes of this Section, the age of a civi l employee \nshall be calculated on the basis of the age to be s et from the birth \nday or year inscribed in the certificate of educati onal institute \nsubmitted by him/her at the time of joining the ser vice or the age to \nbe set from the birth day or year inscribed in the citizenship \ncertificate or the age to be set from the birth day  or year inscribed in \n                                                   \n/oneinv  Amended by the First Amendment. \n \n \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 57  \nwww.lawcommission.gov.np \nthe sheet roll/personal details filled up by him/he r at the time of \njoining the service, at whichever age he/she gets r etired earlier. \n/oneinv34.  Power to award retirement : Government of Nepal may, in the \nfollowing circumstances, retire any civil employee from the service:  \n(a) If any civil employee is proved to have provide d or attempted \nto provide secret governmental documents, deeds or \ninformation under his/her custody or obtained by hi m/her in \nany manner to any unauthorized person or body, \n(b) If any civil employee is proved to have committ ed an \nirresponsible conduct contrary to the dignity of hi s/her post, \nby maintaining undesirable contact with any foreign  country, \norganization or citizen contrary to the national in terests. \n▲\n34A. Special provision in respect of incapacitated employee : If it \nis certified by the medical board constituted by Go vernment of \nNepal that any civil employee is unable to serve re gularly owing to a \nphysical or mental disease, Government of Nepal may  retire that \nemployee, by adding a service period of Seven years  in maximum to \nhis/her service period.  \n/twoinv/twoinv /twoinv/twoinv35.  Voluntary retirement :  (1) Any civil employee who is eligible to \nreceive pension and has completed the age limit of Fifty years may \nvoluntarily retire from the service on such terms a nd within such \nperiod as set forth and specified in a Notification  published by \nGovernment of Nepal in the Nepal Gazette. A service  period not \nexceeding Seven years shall be added and the total service period \nshall be fixed for pension in such a manner that th e age does not \ncross Sixty years in the case of an employee who jo ined the civil \nservice before the 21st Kartik of the year 2049(6 November 1992) \n                                                   \n \n▲   Inserted by the First Amendment.  \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 58  \nwww.lawcommission.gov.np \nand the age does not cross Fifty Eight years in the  case of an \nemployee who joins the civil service on or after th at date, out of the \nemployees who so retire voluntarily.  \nProvided that, in the case of the employee who has become \nredundant because of non-adjustment in position or who is holding a \npost not necessary for Government of Nepal, separat e facilities and \nterms may be specified and application for voluntary  retirement may \nbe invited by a Notification in the Nepal Gazette. \n(2) Notwithstanding anything contained in Sub-secti on (1), if \nan employee who is eligible to have pension and has  completed the \nage limit of fifty years intends to have voluntary retirement, he/she \nmay be retired by promoting him/her to one level hi gher post if \nhe/she has served as per Sub-section (3) of Section  37 in the event \nthat he/she is entitled to promotion to one level h igher post pursuant \nto Section 20A. of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Gratuity : (1) If any civil employee, who has served for Five years", "content": "or more but has not completed the period required f or pension, \nretires or leaves service by getting resignation ac cepted or is \nremoved from the post without being disqualified fo r government \nservice in the future, he/she shall receive gratuit y at the following \nrate:  \n(a) In the case of the civil employee who has serve d \nfrom Five years to Ten years, Half the last \nmonth's salary for each year of his/her service, \n(b) In the case of a civil employee who has served \nfor more than Ten years up to Fifteen years, the \nlast One month's salary for each year of his/her \nservice, \nwww.lawcommission.gov.np \n \n 59  \nwww.lawcommission.gov.np \n(c) In the case of a civil employee who has served \nfor more than Fifteen years but less than Twenty \nyears, the last One and Half month's salary for \neach year of his service. \n(2) Notwithstanding anything contained in Sub-secti on (1), no \ngratuity shall be paid to any civil employee who is  proved to have \nlied about citizenship or age or qualification with  the intention of \nentering into or continuing to hold the government service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Pension : (1) A civil employee who has been in government s ervice", "content": "for a period of Twenty years or more shall be entit led to a monthly \npension at the following rate: \nTotal year of service X amount of the last salar y \n      50 \nProvided that: \n(1) No civil employee who has been dismissed from \nthe service with being disqualified for \ngovernment service in the future shall be entitled \nto the pension pursuant to this Section. \n(2) No pension shall be paid to any civil employee \nwho is proved to have lied about citizenship or \nage or qualification with the intention of \nentering into or continuing to hold government \nservice. \n•(1a) Notwithstanding anything contained in Sub-sect ion (1), \nin the case of not obtaining the pension by the ser vice period due to \ncompulsory retirement to the employees appointed in  a class or post \nas maximum age of Forty years and appointed pursuan t to Sub-\n                                                   \n•  Inserted by the Second Amendment \nwww.lawcommission.gov.np \n \n 60  \nwww.lawcommission.gov.np \nsection (2) of Section 10, pension shall be provide d by adding up to \ntwo years in service period to such employee . \nProvided that, this provision shall not be applicab le to the \nemployees who retired before the commencement of this  sub-\nsection. \n(2) Notwithstanding anything contained in Sub-secti on (1), \nthe minimum amount of pension shall not be less tha n half the \namount of basic figure of salary of the incumbent c ivil employee of \nthe same post ▲ and the maximum amount thereof shall be more \nthan the basic scale of salary of the incumbent civ il employee of the \nsame post . \n/oneinv(3) If any civil employee who has been in service i n the civil \nservice since 21 Kartik  2049 (6 November 1992) ago has already \ncompleted the service period of thirty years, he/sh e may retire from \nservice voluntarily. The total service period of th e civil employee \nwho has so retired voluntarily from service or who has ipso facto  \nretired pursuant to Section 33 owing to the complet ion of 58 years \nof age upon having been in service in the civil ser vice since 21 \nKartik 2049 (6 November 1992) ago shall be set by adding s uch \nremaining period as required for him/her to complet e sixty years of \nage. \n/oneinv(4) If any employee who has completed a service per iod of \nfifteen years dies, a maximum period of Five years shall be added to \nhis/her service period, and his/her family shall be  allowed to receive \neither pension or gratuity, whichever that family c hooses. \n(5) If any person who is receiving pension on accou nt of \nhis/her earlier service in any government post is a ppointed to the \ncivil post later, he/she shall be entitled to pensi on pursuant to this \n                                                   \n▲   Inserted by the First Amendment. \n/oneinv  Amended by the First Amendment. \n \n \nwww.lawcommission.gov.np \n \n 61  \nwww.lawcommission.gov.np \nSection, with the addition of the period of his/her  earlier service to \nthat of his/her subsequent service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Increment in pension : Where the salary of the incumbent civil", "content": "employee is increased, two-third amount of the incr ement in the \nbasic figure of salary shall also be added to the a mount of pension of \nthe retired civil employee of the same post. \n۩Provided that, this provision shall not be applicab le to the \ncivil employee entitled to pension pursuant to Sect ion 39B.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Family pension and gratuity : (1) If any civil employee dies", "content": "while in service or prior to completion of seven ye ars after he/she \nstarted to receive pension, a gratuity or pension a s provided for in \nSection 36 or 37 shall be provided to his/her famil y or minor brother \nor unmarried sister.  \nProvided that, in the case of pension, such pension  shall not \nbe available for more than Seven years. No pension shall be \nprovided to the family of the civil employee, who d ied prior to \ncompletion of Seven years after he/she started to r eceive pension, \nafter completion of Seven years. \n(2) Notwithstanding anything contained in Sub-secti on (1), if \nthe recipient of such pension is a minor, he/she sh all be entitled to \nsuch pension until he/she attends majority. \n(3) The widower husband or widow wife of a civil em ployee \nshall be entitled, for life, to half the amount of pension receivable by \nsuch employee from the date of expiration of the pe riod during \nwhich such widower husband or widow wife is entitle d to family \npension pursuant to Sub-section (1) by reason of th e death of her \nhusband or his wife while in service or prior to co mpletion of Seven \n                                                   \n۩Proviso inserted by the Second Amendment. \n  \nwww.lawcommission.gov.np \n \n 62  \nwww.lawcommission.gov.np \nyears after he/she started to receive pension and f rom the date of \ndeath of such employee where such widower husband o r widow wife \nis not entitled to such family pension or where his  wife or her \nhusband dies after completion of seven years after he/she started to \nreceive pension. \n۩Provided that, if such widower husband or widow wif e \nconcludes another marriage, he or she shall not be entitled to this \nkind of pension facility. \n•(3a) Notwithstanding anything contained in Sub-sect ion (3), \nif the pension receiver widower husband or widow wi fe dies or \nhe/she marries with other, such pension amount shal l be provided as \nprescribed to minor children until they attain majo rity. \n(4) Where the salary of incumbent civil employee is  \nincreased, the two-thirds of the total amount incre ased in the figure \nof basic salary shall also be added to the amount o f family pension \nof the person receiving family pension pursuant to sub-sections (1), \n(2) and (3). \n(5) If any employee dies prior to receiving any amo unt to \nwhich that employee is entitled under this Act, suc h amount shall be \npaid to the person from amongst his/her family memb ers who is held \nto be entitled to the gratuity or pension of that e mployee pursuant to \nthis Act. \n(6) In providing gratuity or pension, if the deceas ed civil \nemployee has nominated any member of his/her family  or his/her \nminor brother or unmarried sister, gratuity or pens ion shall be \nprovided to such person, and if, for any reason, gr atuity or pension \ncannot be provided to such person or if nobody has been nominated, \n                                                   \n۩Proviso inserted by the Second Amendment. \n \n•  Inserted by the Second Amendment \nwww.lawcommission.gov.np \n \n 63  \nwww.lawcommission.gov.np \nit shall be provided to such person from amongst th e members of \nhis/her family as may be deemed appropriate by Gove rnment of \nNepal. \n▲ 39A. Pension and gratuity of disappeared employee : (1) If any \ncivil employee who has served in the civil service has disappeared \nand whose whereabouts have not been traced until th e prescribed \nperiod whether he/she is dead or alive, the amount of gratuity or \npension to which such employee is entitled pursuant  to Section 36 or \n37 shall be provided to his/her family. \n(2) Notwithstanding anything contained in Sub-secti on (1), \nhis/her family shall be provided with the family pe nsion equal to the \nfull amount of pension for up to Seven years if he/ she who is \nentitled to pension pursuant to Section 37 disappea rs prior to \nreceiving pension and for up to the period remainin g to complete \nSeven years if he/she disappears after starting to receive pension, \nand after that period, his/her wife or husband shal l be provided with \nfamily pension equal to half the amount of pension for life. \n(3) If the employee disappeared is traced subsequen tly, the \ngratuity as referred to in Section 36, if not paid yet, or the amount of \npension receivable under Section 37 shall be provid ed to him/herself \nfrom the date on which he/she claims for the same. \nProvided that, the person traced subsequently shall  not be \nentitled to claim such amount of gratuity, pension or family pension \nas has already been paid pursuant to Sub-section (1 ) or (2). \n•39B. Special provisions relating to gratuity and pe nsion : (1) \nGovernment of Nepal shall set up a separate gratuit y and pension \nfund for purposes of providing gratuity and pension  to civil \n                                                   \n▲   Inserted by the First Amendment. \n•  Inserted by the Second Amendment . \nwww.lawcommission.gov.np \n \n 64  \nwww.lawcommission.gov.np \nemployees appointed after the date of Notification in Nepal Gazette. \nAn amount at the rate of at least Ten per cent of t he monthly salary \nof such employees shall be deducted, and Government  of Nepal \nshall, adding the amount equal to Ten per cent of t he monthly salary \nto such amount, deposit the total amount in that fu nd.  \n(2) The gratuity and pension related provisions con tained in \nSub-section (1a) of Section 32, Section 34A., 35, 3 6,37, 38, 39 and \n39A. shall not be applicable in the case of the civ il employees to be \nappointed after the publication of notice pursuant to Sub-section (1). \n (3) Government of Nepal shall provide the amount e quivalent \nto deducted monthly salary pursuant to Sub-section (1) at the time of \npayment of salary to the employee. \n(4) Notwithstanding anything contained in Sub-secti on (3), a \ncivil employee who has been dismissed from the serv ice with being \ndisqualified for government service in the future p ursuant to Sub-\nclause (2) of Clause (b) of Section 59 shall be ent itled to receive a \nlump sum of the total amount deducted from his/her salary to that \nfund and interest as well as profit accrued therein  and therefrom. \n (5) Other provisions relating to the management an d \noperation of the amounts to be deposited in the gra tuity and pension \nfund set up pursuant to Sub-section (1), procedures  for the deduction \nof funds, payment of fund deducted amounts for purp oses of gratuity \nand pension and fund deductions shall be as prescri bed. \n•39C. Special provision of family pension : (1) Notwithstanding \nanything contained elsewhere in this Act, if any ci vil employee in \nthe course of duties specified by the government fo r the work \nperformance dies due to insurgency and his/her serv ice period is less \n                                                   \n•  Inserted by the Second Amendment.  \nwww.lawcommission.gov.np \n \n 65  \nwww.lawcommission.gov.np \nthan Twenty years, the pension as per this Act shal l be provided to \nthe husband or wife by adding remaining service per iod.  \n(2) The person receiving pension pursuant to Sub-se ction (1) \nshall not receive family pension or gratuity pursua nt to Section 39. \n(3) If person receiving pension as per this Section  marries \nwith other, he/she shall not receive such pension. \n(4) While increasing the salary of the civil employ ee, Two \nthird amount of the increased salary shall be added  to the person \nreceiving the family pension. \n(5) If the person receiving pension as per this Sec tion dies or \nhe/she marries with other, such pension amount shal l be provided to \nminor son, daughter, if any, of the deceased employ ee until they \nattain majority. \n•39D Special economic facility : If a civil employee dies while in \nservice, his/her near heir shall be provided with a  lump sum of One \nHundred Fifty Thousand Rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Reference of salary : (1) Wherever in this Chapter and in Chapter", "content": "5, a reference of salary is made, it shall mean the  concerned civil \nemployee's salary amount (including salary incremen t) for the time \nbeing.  \n(2) For purposes of Sections 36 and 37, the term \"l ast salary\" \nshall mean the concerned employee's salary at the t ime of his/her \nretirement, and if any civil employee has been on e xtra-ordinary \nleave or under suspension at the time of such retir ement, the amount \nof full salary shall be computed even for such peri od. \n                                                   \n•  Inserted by the Second Amendment.  \nwww.lawcommission.gov.np \n \n 66  \nwww.lawcommission.gov.np \n/twoinv/twoinv /twoinv/twoinv40A. Provisions relating to insurance facility : (1) The Government \nof Nepal shall establish a fixed term ( Sabadhik ) life insurance fund \nfor the civil employee insurance.  \n(2) A sum of Two Hundred Rupees shall be deducted f rom the \nmonthly salary of each civil employee and deposited  in the fund \npursuant to Sub-section (1), and the Government of Nepal shall add \nthe amount equal thereto and make the Twenty year t erm life \ninsurance for the insured sum of One Hundred Thousa nd Rupees. \nFrom the amounts deposited in that insurance fund, the insured sum \nand bonus shall be paid to the employee at the time  of his/her \nretirement. \n(3) If any civil employee who has made deduction pur suant to \nSub-section (2) dies before the completion of Twent y years of \nservice period, an amount of One Hundred Thousand R upees shall \nbe provided to his/her family. The following amount  shall be \nprovided to the compulsory retired civil employee. \n(a) Ten Thousand Rupees for deducting the amount \nof less than One year. \n(b) Twenty Five Thousand Rupees for deducting the \namount of more than One year and less than Five \nyears. \n(c) Fifty Thousand Rupees for deducting the amount \nof more than Five year and less than Ten years. \n(d) Seventy Five Thousand Rupees for deducting the \namount of more than Ten year and less than \nFifteen years. \n(e) One Hundred Thousand Rupees for deducting \nthe amount of more than Twenty years. \n                                                   \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 67  \nwww.lawcommission.gov.np \nProvided that, if the deposited amount, \ninterest and dividend be higher than the above \nmentioned amount, the higher amount shall be \nprovided from the fund. \n(4) If any civil employee who has made deduction pur suant to \nSub-section (2) retires from the service for any re ason whatsoever, \nprior to the twenty years deduction of amount,  an amount equal to \nthe surrender ( Samarpan ) value shall be provided to such employee. \n(5) Notwithstanding anything contained in sub-secti ons (2) \nand (3), the retired employee shall provide continu ity as maturity to \nthe fixed term life insurance amount in twenty or l ess than Twenty \nyears. \nProvided that, Government of Nepal shall not provid e any \namount for the same.  \n(6) Other provisions relating to the fixed term lif e insurance \nfund shall be as prescribed. \n▲\n40B. Provisions relating to study, training or stud y tour : (1) The \nconcerned Ministry, Commission or Secretariat shall , in order to \nsend the employees under it for study, training or study tour, prepare \na description thereon and forward it to the Ministr y of General \nAdministration each year. \n(2) The Ministry of General Administration must, up on \nreceipt of the description pursuant to Sub-section (1), specify the \nnumber on subject-wise basis for study, training or  study tour and \nforward a description thereof to the National Plann ing Commission. \n(3) There shall be a committee as follows to allocat e the \nopportunities of study, training or study tour rece ived by the \n                                                   \n▲   Inserted by the First Amendment. \nwww.lawcommission.gov.np \n \n 68  \nwww.lawcommission.gov.np \nNational Planning /twoinv/twoinv /twoinv/twoinvCommission and other governmental institution  \nin the name of Government of Nepal to all the servi ces \nproportionately: \n(a) Chief Secretary of the \nGovernment of Nepal \n \nChairperson \n \n(b) Secretary at the Ministry of \nFinance \nMember \n(c) Secretary at the National \nPlanning Commission  \n \nMember \n(d) Secretary at the Ministry of \nGeneral Administration \nMember \nSecretary \n(4) The Ministry of General Administration shall di stribute \nopportunities as per the decision of the committee referred to in \nSub-section (3) \n(5) The criteria for making nomination for a study,  training or \nstudy tour shall be as prescribed. \n▲\n40C.Period for which service to be done upon comple tion of \nstudy, training or study tour : Any civil employee who pursues a \nstudy, training or goes on a study tour on the nomi nation of \nGovernment of Nepal must, upon completing such a st udy, training \nor study tour, serve in the Ministry or Office wher e he/she was in \nservice before going on for such study, training or  study tour for up \nto the period as mentioned below in a compulsory ma nner, subject to \nthis Act: \n                                                   \n/twoinv  Amended by the Second Amendment. \n▲   Inserted by the First Amendment. \n \nwww.lawcommission.gov.np \n \n 69  \nwww.lawcommission.gov.np \n \nPeriod of study, training or  Minimum period for wh ich \nstudy tour service is to be done \n(a) Up to Three months One year \n(b) From Three months to Six months One and half ye ar \n(c) From Six months to Nine months Two years \n(d) From Nine months to One year Three years \n(e) From One year to Two years Four years \n(f) From Two years to Three years Five years \n(g) From Three years to Four years Seven years \n(h) From Four years to Five years Eight years \n/twoinv/twoinv /twoinv/twoinv40D. Bond to be executed : (1) Any civil employee shall, before going \nfor having study, training or study tour, by the no mination of \ngovernment, execute a bond to the effect that he/sh e shall return \nupon completing such study, training or study tour and carry out \nservice as referred to in Section 40C. \n(2) If any civil employee does not return to the se rvice after \ncompleting the study, training or study tour or doe s not complete the \nperiod of service required to be carried out under Section 40C., the \nsalary, allowances received by him/her during the p eriod of the \nstudy, training or study tour and other amounts men tioned in the \nbond, as well, shall be realized from such employee  as government \ndues if such salary, allowances and other amounts b e not returned \nwithin the prescribed period. \n(3) Any civil employee who, upon obtaining the prio r \napproval of the competent, has gone to carry out st udy, training or \n                                                   \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 70  \nwww.lawcommission.gov.np \nstudy tour, shall execute a bond to the effect that  he/she shall carry \nout service as equal to the study training or study  tour after the \ncompletion of study, training or study tour. \n(4) If a civil employee who has gone for study purs uant to \nsub-sections (1) and (3) does not come for service or does not \ncomplete the service period, the duration of such s tudy, training or \nstudy tour shall not be counted in service period o f such employee. \n(5) Notwithstanding anything contained elsewhere in  this \nSection, if an employee who has gone for study, tra ining or study \ntour gets compulsory retirement or dies, any amount  shall not be \nforfeited from him/her or him/her family for the no n-completion of \nservice pursuant to Section 40C.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 7", "title": "Chapter 7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "41", "title": "Punctuality and regularity : Each civil employee must attend", "content": "his/her office regularly during the time appointed by Government of \nNepal and must not remain absent from the duty with out having \nprior sanction of leave as far as possible.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Discipline and obedience : (1) A civil employee must remain in", "content": "discipline and perform his/her duties with honesty a nd readiness.  \n(2) A civil employee must expeditiously carry out a ny orders \ngiven by his/her superior officer on matters relati ng to governmental \nbusiness. \n(3) A civil employee must show due respect to all t he \nemployees superior to him/her and treat his/her sub ordinate \nemployees properly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Restriction on using political or undue influen ce : No civil", "content": "employee shall, with intention to satisfy his/her p ersonal interests on \nwww.lawcommission.gov.np \n \n 71  \nwww.lawcommission.gov.np \nmatters relating to his/her service, exert or attem pt to exert any \npolitical or other undue influence over any other c ivil employee.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Restriction on taking part in politics : No civil employee shall", "content": "take part in politics.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Restriction on criticizing Government :  (1) No civil employee", "content": "shall, on his/her real or pseudo name or anonymity,  publish any \nfeature article, provide any news to the press, bro adcast a speech \nthrough radio or television etc., make any public sp eech or publish \nany statement in such a manner as to be contrary to  the policies of \nGovernment of Nepal or to undermine the mutual rela tionship \nbetween Government of Nepal and the people or the r elationship \nwith any foreign country. \n(2) Notwithstanding anything contained in Sub-secti on (1), it \nshall not bar the publishing or broadcasting of any  feature article in \nsuch a manner as not to be contrary to the prevaili ng law and the \npolicies of Government of Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Restriction on publishing news relating to gove rnmental", "content": "business : No civil employee shall, without being authorized  by \nGovernment of Nepal, provide or divulge, directly o r indirectly, to \nany other  unauthorized employee or non-governmental person or  \npress any confidential matter which was known to hi m/her in the \ncourse of performing the governmental duty or any m atter \nprohibited by law or any document or news written or  collected by \nhim/her. This restriction shall also be applicable to a person who has \nbeen relieved of the government service for any rea son whatsoever.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Restriction on receiving gift, present, donatio n etc. and", "content": "borrowing : (1) No civil employee shall, without prior approv al of \nGovernment of Nepal, accept a gift, donation, prese nt or \ngratification of any kind either by him/herself or through any \nwww.lawcommission.gov.np \n \n 72  \nwww.lawcommission.gov.np \nmember of his/her family, or ask for donation or bo rrow any loan \nfrom any person concerned with any government busin ess, in such a \nmanner as to affect the government business in any manner. \n(2) If any civil employee happens to receive any pr esent from \nany foreign government or any representative of suc h foreign \ngovernment, he/she must inform Government of Nepal about it and \nshall act accordingly as sanctioned.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Restriction on establishing and operating compa ny and", "content": "carrying on trade or profession : (1) No civil employee shall, \nwithout prior approval of Government of Nepal, carr y out the \nfollowing acts:  \n(a) To participate in the establishment, registrati on \nor operation of any bank or company, \n(b) To carry on any trade or profession requiring \nregistration according to the prevailing laws, \n(c) To accept any kind of employment elsewhere. \n(2) Notwithstanding anything contained in Sub-secti on (1), a \ncivil employee may carry out any literary, scientif ic or artistic works \nin a manner not to be contrary to the policies of G overnment of \nNepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Restriction on taking part in election : No civil employee shall", "content": "take part in an election to any political post nor shall solicit vote for \nanyone nor shall exercise influence of any kind in the election.  \n  Provided that, this shall not bar the exercise of  his/her right to \nvote conferred under the prevailing laws, without r evealing whom \nhe/she has voted or intends to vote for.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Restriction on agitation and strike : No civil employee shall", "content": "perform an agitation, participate in a strike or en tice anyone to \nwww.lawcommission.gov.np \n \n 73  \nwww.lawcommission.gov.np \nperform such acts in a manner to undermine the sove reignty and \nintegrity of the Kingdom of Nepal, the law and orde r situation of the \ncountry, external relations and public decency, make  contempt of \ncourt, create hatred among the peoples of various c astes, tribes, \nreligions, classes, regions and communities or aid and abet any \ncrime.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Restriction on staging strike, detention and Gherao : No civil", "content": "employee shall stage any strike or pen-down action and exert any \npressure inflicting physical or mental suffering or  entice other \npersons to commit such acts in a manner to cause hi ndrance or \nobstruction to any office or officer in the perform ance of the duties \nrequired by law. \n/twoinv/twoinv /twoinv/twoinv52. Restriction on making representation : No civil employee shall \nmake representation on behalf of any person or grou p, except for \nmaking petition to the concerned body or official e ither by \nhim/herself or through his/her attorney in respect of any grievance \ncaused to him/her. \nProvided that, nothing in this Section shall be dee med to bar \nthe carrying out of any work regarding post respons ibility of civil \nemployee and representation on behalf of the authen tic trade union \nof the civil employees formed pursuant to Sub-secti on (3) of Section \n53.  \n/twoinv/twoinv /twoinv/twoinv53. Provision relating to professional organization  of civil \nemployees : (1) The civil employees may form an organization \nunder the provisions of this Act. \n(2) The following provisions shall be complied with  while \nforming the trade union pursuant to Sub-section (1) . \n                                                   \n/twoinv  Amended by the Second Amendment. \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 74  \nwww.lawcommission.gov.np \n(a) The employees of gazetted third class or lower \nthan that except the gazetted class employees \nwho work as the head of the office, may form a \ntrade union of civil employees at the national \nlevel and receiv membership for their \nprofessional entitlement and welfare. \n(b) The registration of the trade union of civil \nemployees shall be made in the Department of \nLabour and Employement Promotion. \n(3) The authentic trade union of civil employees sh all be \nformed as follows: \n(a) The member of the trade union of civil \nemployees as formed pursuant to Sub-section (1) \nmay form authentic trade union of civil \nemployees with appointing officials. \n(b) The authentic trade union of civil employees \nshall have the right to submit own professional \ndemands and conduct social dialogue and \ncollective bargaining at the concerned institution \nat the district, departmental and national levels. \nIn the case of not forming the authentic trade \nunion of civil employees, the trade union of civil \nemployees formed pursuant to Sub-section (1) \nmay conduct collective bargaining with mutual \nconsent of each other. \n(c) The other provisions relating to authentic trad e \nunion of civil employees shall be as prescribed. \n(4) The functions, duties and powers of the trade u nion of \ncivil employees shall be as follows: \nwww.lawcommission.gov.np \n \n 75  \nwww.lawcommission.gov.np \n(a) The duties of the trade union of civil employee s \nformed pursuant to sub-sections (1) and (3) are \nto provide suggestion and assistance to the \nGovernment of Nepal about effective and \ndynamic civil service while taking account of the \nprotection and promotion of employees’ right \nand interest.  \n(b) The trade union of civil employees may conduct \ncreative and artistic work along with asembly, \ntraining and symposim. \n(c) The trade union of civil employees shall have \nthe right to form association, receive \nmembership of such association, receive \nmembership of an international association and \nrepresent on behalf of the association. \n(5) The Government of Nepal may take suggestions fr om the \nauthentic trade union of civil employees while maki ng law relating \nto civil service. \n(6) The competent authority shall have to manage th e transfer \nof the officials of the authentic trade union of ci vil employees and \nnational level trade unions formed pursuant to Sub- sections (1) and \n(3) on their demand to their appropriate working ar ea. \n(7) The tour up to thirty days in one year may prov ide to the \ncentral officials and members of the national level  trade union \nformed pursuant to Sub-sections (1) and (3) to part icipate a seminar, \nworkshop, assembly, work related with the organizat ion at the \ndomestic and international level without causing fi nancial obligation \nto the Government of Nepal . \nwww.lawcommission.gov.np \n \n 76  \nwww.lawcommission.gov.np \n(8) The other provisions of registration, condition  thereon and \nprocess relating to trade union of civil employees shall be as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Statement of property : Each civil employee must submit a", "content": "statement of his/her property.  \n•54A. Prohibition on torture : (1) No civil employee shall subject any \none to torture.  \n(2) No civil employee shall commit sexual abuse. \n•54B.  Other conduct : (1) In discharging duties in his/her office, a civi l \nemployee must treat all in a decent manner.  \n(2) The civil employee must bear the responsibiliti es which \nmay arise according to his/her office and post and perform works in \nan impartial, fair, efficient and prompt manner. \n(3) The civil employee must not use or consume any \ngovernment property for domestic use. \n(4) The civil employee must not depute any governme nt \nemployee, appointed as to get salary by the governm ent service to \ndomestic work except office work. \n•54C. Treatment to stakeholders : (1) The civil employee must accord \ndecent treatment to the stakeholders related with hi s/her works.  \n(2) A clear information, inter alia , on the matters and process \nrelated with the work of the stakeholders and the t ime required to \nperform the work must be given to the stakeholders in due time. \n                                                   \n•  Inserted by the Second Amendment. \n \n \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 77  \nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "To keep conduct compatible with own service and  post : Each", "content": "civil employee must also keep his/her conduct compa tible with \nhis/her service and post.  \n▲ 55A. Powers to warn : If any civil employee is not punctual, does not \ncarry out the order given by the employee superior to him/her on \nmatters relating to any government business or beco mes reckless or \nslow on office works, the concerned supervisor may give a warning \nto such an employee, with setting out the reason th erefor; and \nrecords thereof must be maintained in the sheet rol l/personal details \nfile of the concerned employee.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 8", "title": "Chapter 8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "56", "title": "Security of service of civil employee : No civil employee, other", "content": "than the following civil employee, shall be removed  or dismissed \nfrom the civil service without providing him/her wi th a reasonable \nopportunity to furnish proofs his/her defense: \n(a) Who has been convicted by a court of a criminal  offence \ninvolving moral turpitude, \n(b) Who is holding a temporary  post, \n(c) Who has disappeared and whose whereabouts are n ot known \nor there are sufficient grounds that it is not poss ible to \nestablish contact with him/her. \n•(d)  Who is convicted by a court of a corruption ch arge.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Saving of civil employees : (1)No case may be instituted against", "content": "any civil employee in respect of any government bus iness performed \nby him/her considering it to be the carrying out of  the duties of \n                                                   \n▲   Inserted by the First Amendment. \n \n•  Inserted by the Second Amendment.  \nwww.lawcommission.gov.np \n \n 78  \nwww.lawcommission.gov.np \nhis/her post, without fulfilling the procedures as mentioned in Sub-\nsection (2). \n(2) In order to institute a case against any civil employee \npursuant to Sub-section (1), an approval of the Aut hority shall be \nrequired in respect of a criminal case; and the fol lowing matters \nhave to be observed in respect of a civil case: \n(a)  Two months have elapsed after a written notice  \nstating the reasons for instituting the case and \nthe name and address of the plaintiff and of \nhis/her attorney, if any, has been delivered to the  \nAuthority or the concerned civil employee or \nsent by post through a registered mail and a copy \nof such notice has been submitted to \nGovernment of Nepal. \n(b) The case has been filed within eight months \nfrom the date of cause of action. \n(3) In respect of any act performed by any civil em ployee in \nthe course of discharging the duties of his/her pos t while he/she was \nincumbent, no case may be instituted against him/he r without the \napproval of Government of Nepal, even after the ter mination of \nhis/her service. \n(4) If Government of Nepal gives approval to instit ute a case \npursuant to Sub-section (3), Government of Nepal sh all defend on \nhis/her behalf.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Security of conditions of service : The conditions of service", "content": "relating to salary, gratuity, pension and other fac ilities of any civil \nemployee prevailing at the time of his/her appointm ent shall not, \nwithout his/her consent, be so altered as to cause adverse effects on \nhim/her. If any subsequent amendment causes adverse  effects, in \nwww.lawcommission.gov.np \n \n 79  \nwww.lawcommission.gov.np \nany manner, on such conditions of service of any ci vil employee \nwho is already incumbent prior to such amendment, s uch amended \nprovisions shall not be applicable to him/her in ab sence of his/her \nwritten consent to the application of such provisio ns.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 9", "title": "Chapter 9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "59", "title": "Punishment : A civil employee may be subjected to the", "content": "/oneinvdepartment punishmen t as follows, if there exist appropriate and \nsufficient reasons: \n/twoinv(a) Ordinary Punishment : \n(1) Censure, \n(2) Withholding of promotion for up to two years or  \nwithholding of a maximum of two salary increments, \n(3) Withholding of promotion for two to five years,  or \nwithholding of a maximum of two to five salary \nincrements, \n (b) Special punishment : \n(1) Removal from service, without being disqualifie d for \ngovernment service in the future. \n(2) Dismissal from service, with being disqualified  for \ngovernment service in the future. \n/twoinv60. Censure or withholding of promotion for up to t wo years or \nwithholding of a maximum of two salary increments : \nPunishment of censure or withholding of promotion f or up to two \n                                                   \n/oneinv  Amended by the First Amendment. \n/twoinv  Amended by the Second Amendment. \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 80  \nwww.lawcommission.gov.np \nyears or withholding of a maximum of two salary inc rements may be \nimposed on a civil employee, in any of the followin g circumstances: \n(a) If his/her performance did not found satisfactor y, \n(b) If he/she fails to hand over the charges pursua nt to the \nprevailing law, \n(c) If he/she is given warning for up to two times a year under \nSection 55A., \n(d) If he/she violates the matters relating to cond uct mentioned in \nthis Act and the Rules framed hereunder,  \n(e) If he/she fails to observe any direction given by the official \nsuperior to him/her in respect of his/her frequent disregard of \ngrievances and complaints of the stakeholders, \n(f) If the office-bearer obliged to enforce, or cau se to be \nenforced, the job description fails to do so. \n•60A.Withholding of promotion for two to five years or \nwithholding of a maximum of two to five salary incr ements \nor demoting to the basic scale of the post : Punishment of \nwithholding of promotion for up to five years or wi thholding of a \nmaximum of five salary increments or demoting to th e basic scale of \nthe post held by him/her may be imposed on a civil employee, in any \nof the following circumstances: \n(a) If he/she commits breach of discipline, \n(b) If he/she violates the matters relating to cond uct mentioned in \nthis Act and the Rules framed hereunder,  \n(c) If he/she fails to settle advances pursuant to the prevailing \nlaw, \n                                                   \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 81  \nwww.lawcommission.gov.np \n(d) If he/she fails to observe any direction given in respect of \nirregularities found from management audit. \n(e) If he/she frequently absent in the office witho ut prior notice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Removal or dismissal from service : (1) A civil employee may", "content": "be removed from serve, without being disqualified f or government \nservice in the future, in any of the following circ umstances:  \n(a)  If the civil employee fails to perform the dut ies \nor responsibilities of his/her post due to his/her \nown incapacity. \n(b) If he/she frequently violates the matters relat ing \nto conduct. \n(c) If he/she frequently consumes alcoholic \nsubstances during the office hours. \n(d) If he/she frequently commits acts of indiscipli ne. \n(e)  If he/she takes part in politics. \n(f) If he/she frequently neglects the responsibilit ies \nof his/her post. \n(g) If he/she absents himself/her from his/her offi ce \ncontinuously for ninety days without having \nsanction of a leave. \n(2) A civil employee may be dismissed from service,  with \nbeing disqualified for government service in the fu ture, in any of the \nfollowing circumstances: \n(a) If he/she is convicted by a court of a criminal  \noffence involving moral turpitude. \n(b) If he/she commits corruption. \nwww.lawcommission.gov.np \n \n 82  \nwww.lawcommission.gov.np \n•61A.  Special provisions relating to departmental action and \npunishment : (1)  Notwithstanding anything contained elsewhere in \nthis Act, if, pursuant to the Commission for the In vestigation of \nAbuse of Authority Act, 2048 (1991), that Commissio n, and, \npursuant to the prevailing law, the concerned body writes for \ndepartmental action against any civil employee, dep artmental \npunishment must be imposed accordingly, after fulfi lling the \nrequired procedures . \n(2)  Notwithstanding anything contained elsewhere in thi s Act, \nif any civil employee is found absent in office wit hout approved \nleave, he/she may be registered as absent and his/h er salary may be \ndeducted. Such period shall not be counted in the s ervice period. \n(3) Notwithstanding anything contained elsewhere in  this Act, \nno office-bearer shall allow a civil employee who r emains absent for \na period exceeding ninety consecutive days to atten d the office, by \nmarking him/her as non-attendant. Departmental acti on shall be \ntaken against the office-bearer who so allows offic e attendance; and \nthe salary and allowances, as well, received by the  employee who \nhas been so allowed to attend the office shall be r ealized from the \noffice-bearer who has so allowed office attendance as governmental \ndues.  \n/twoinv62. Departmental punishment awarding official : (1) The following \nauthority shall have the powers to issue order of p unishment to the \ncivil employee pursuant to Clause (b) of Section 59 .  \n(a) The Government of Nepal for the employee \nworking in first class and above that post. \n                                                   \n•  Inserted by the Second Amendment. \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 83  \nwww.lawcommission.gov.np \n(b) Concerned institution special class official fo r \nthe employee working in gazetted second and \nthird class. \n(c) Concerned institution departmental head or \ngazetted head of the office for the non gazetted \ncivil employees. \n(2) The authority to issue order of punishment purs uant to \nClause (a) of Section 59 shall be as prescribed. \n/twoinv63. Delegation of powers to award departmental puni shment : \nGovernment of Nepal may, by a Notification in the N epal Gazette, \ndelegate the powers of any official empowered to is sue order of \npunishment pursuant to Section 62 to any other offi cial specified in \nthat Notification, to be exercised for such period as specified in that \nNotification.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Powers to suspend : (1) If the investigation of any charge", "content": "mentioned in Section 61 is to be conducted in respe ct of any civil \nemployee, the official empowered to issue order of punishment may \nsuspend such a civil employee until the conclusion of the \ninvestigation. \nProvided that, generally suspension shall not be or dered \nunless the following circumstance exists: \n(a) Where there is a possibility that he/she can \ncollect false evidence or conceal any evidence \nagainst him/her if he/she is not suspended and is \nallowed to carry out the duties of his/her post, or  \n(b) Where there is a possibility of governmental lo ss \nor damage if he/she is not suspended and is \nallowed to carry out the duties of his/her post. \n                                                   \n \nwww.lawcommission.gov.np \n \n 84  \nwww.lawcommission.gov.np \n(2) The official empowered to issue order of punish ment to a \ncivil employee may give a notice of the charge to h im/her on his/her \nremoval or dismissal from service, and may also sus pend him/her. \n(3) In suspending a civil employee pursuant to Sub- section \n(1), he/she must not be suspended ordinarily for mo re than two \nmonths. The action against the employee must be com pleted within \nthat period. If such action cannot be completed wit hin that period \nbecause of the occurrence of any extra-ordinary cir cumstance and \nthe period of suspension has to be extended, the pe riod of \nsuspension may be extended for up to one month with  the prior \napproval of the Authority. \n(4) Any civil employee arrested and detained for a criminal \ncharge involving moral turpitude shall be deemed to  have ipso facto  \nbeen suspended during the period of such detention.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Termination of suspension : If any civil employee is reinstated in", "content": "his/her post or ▲ the period as referred to in Sub-section (3) of \nSection 64 is complete d or he/she is removed or dismissed from \nservice, his/her suspension shall stand terminated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "66", "title": "Providing opportunity for defense : (1) The official empowered", "content": "to issue order of departmental punishment must, pri or to issuing an \norder of punishment to any civil employee, serve on  him/her a \nnotice, explaining the reason for taking such actio n and give an \nopportunity to defend him/herself within a reasonab le time limit. In \ngiving such opportunity, the charge against him/her  must be clearly \nindicated and the facts and grounds on which each c harge is based \nmust be specified. In such case, the concerned empl oyee must also \nsubmit his/her defense within the time limit; and t he concerned \nofficial must seriously consider the defense so sub mitted. \n                                                   \n▲   Inserted by the First Amendment. \nwww.lawcommission.gov.np \n \n 85  \nwww.lawcommission.gov.np \n(2) The official empowered to issue order of depart mental \npunishment may, if he/she thinks it necessary, cond uct an \ninvestigation either by him/herself or through any other officer. The \nofficer conducting the investigation must follow th e prescribed \nprocedures.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "To propose punishment prior to issuance of orde r of special", "content": "punishment : If the concerned civil employee does not submit \ndefense under Section 66 or if the defense submitte d by such \nemployee is not satisfactory, the official empowere d to issue order \nof departmental punishment must, prior to issuing a n order of \nspecial punishment, ask such civil employee to furn ish an \nexplanation why the proposed punishment intended to  be imposed \non him/her should not be imposed on, within a reaso nable time limit \nin this respect.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "Seeking consultation of Public Service Commissi on : If it", "content": "appears that the defense submitted under Section 66  or the \nexplanation furnished under Section 67 by the conce rned civil \nemployee in the course of action on departmental pu nishment is not \nsatisfactory and punishment is to be imposed on suc h employee, the \nofficial empowered to issue order of departmental p unishment must \npropose the punishment intended to be imposed on th at employee \nand seek consultation of the Public Service Commiss ion.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Constitution, functions and duties of Administr ative Court :", "content": "(1) An Administrative Court shall be constituted, a s prescribed, \nunder the chairpersonship of a person who is a sitt ing or a retired \njudge of the Appellate Court, in order to hear appe als against the \nwww.lawcommission.gov.np \n \n 86  \nwww.lawcommission.gov.np \ndecisions of the official empowered to issue order of departmental \npunishment /scissorschilds-----. \n•(1a) Notwithstanding anything contained in Sub-sect ion (1), \nwhere an appeal against the order of punishment as referred to in \nClause (a) of Section 59 has been filed with any of ficial at the time \nof commencement of this Section and yet to be settl ed, such appeal \nmust be settled by the official with whom it has be en filed.  \n(2) The decision made by the Administrative Court s hall be \nfinal. \n(3) If, on the final settlement of an appeal under this Section \nin regard to any civil employee, his/her service is  to be reinstated by \nvirtue thereof but he/she does not appear within th ree months from \nthe date of receipt of a notice of that decision, i t shall not be \nmandatory to reinstate him/her in the service. \n(4) Other functions and duties of the Administrativ e Court \nand the procedures to be followed by the Court whil e exercising its \njurisdiction or while performing its other function s shall be as \nprescribed. \n(5) The appellant may, if he/she so wishes, appear on the \nappointed days either in person or by his/her attor ney and may have \nhis/her case pleaded by a legal practitioner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Decision not to be affected : No decision shall be affected by any", "content": "minor error which does not cause substantial effect s on the action \nagainst a civil employee conducted by the competent  authority \npursuant to this Act or the Rules framed hereunder.  \n                                                   \n/scissorschilds  Deleted by the Second Amendment. \n•  Inserted by the Second Amendment. \nwww.lawcommission.gov.np \n \n 87  \nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 10", "title": "Chapter 10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "71", "title": "Leave to which civil employee is entitled : The civil employees", "content": "shall be entitled to the following leaves, as presc ribed: \n(a) Casual and Festival Leave; \n(b)  Home Leave; \n(c) Sick Leave; \n(d) Maternity Leave; \n•(d1) Maternity Care Leave; \n(e)  Obsequies Leave; \n(f) Study Leave; \n(g) Extra-ordinary Leave; \n•\n71A.  Unpaid Leave : (1) If the husband or wife of any civil employee is \ndeputed to the foreign based Nepalese Embassy or mi ssion, such \ncivil employee shall get unpaid leave as prescribed . \n(2) The unpaid leave pursuant to Sub-section (1) sh all not be \ncounted in the period of service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "72", "title": "Delegation of powers : /twoinv(1) Government of Nepal may, by a", "content": "Notification in the Nepal Gazette, so delegate the powers conferred \nto it by this Act that such powers may be exercised  by the civil \nemployee or official specified in that Notification .  \nProvided that, no powers conferred by this Act may be \ndelegated by any Act, other than this Act.  \n                                                   \n•  Inserted by the Second Amendment.  \n \n/twoinv  Amended by the Second Amendment. \nwww.lawcommission.gov.np \n \n 88  \nwww.lawcommission.gov.np \n(2) Any official may so delegate the powers conferr ed to \nhim/her by this Act to his/her subordinate civil em ployee that such \npowers are to be exercised under her/his general su pervision. \n▲ 72A.  Management audit : Except in the matters within the domain of \nthe Public Service Commission, the Ministry of Gene ral \nAdministration may supervise, monitor and evaluate as to whether \nthe civil employees in service in different bodies of the Government \nof Nepal have abided by the prevailing law and othe r administrative \nrules and procedures and give direction, and if, in  making such \nsupervision, it appears that departmental action is  to be taken \nagainst any civil employee, it may also recommend s uch action; and \nit shall submit an annual report thereof to the Gov ernment of Nepal. \n/oneinv/oneinv /oneinv/oneinv73. Full salary and allowance to be received on bei ng reinstated \nin civil service : (1) If any civil employee is re-instated in the c ivil \nservice upon annulment by the court of the order of  his/her \nretirement, removal or dismissal from civil service , such employee \nshall be entitled to the salary, allowances, •Festival expense s as well \nas increment in salary, if any, receivable, from th e date of his/her \nretirement, removal or dismissal from civil service  to the date of \nhis/her re-instatement in the civil service. \n(2) If any civil employee who was retired or remove d or \ndismissed from civil service prior to 4th Jestha  of the year 2050 (17 \nMay 1993) is reinstated in the civil service by a c ourt order issued \nafter that date, such employee shall also be entitl ed to the salary, \nallowance and increment in salary pursuant to Sub-s ection (1). \n                                                   \n▲   Inserted by the First Amendment. \n/oneinv  Amended by the First Amendment. \n \nwww.lawcommission.gov.np \n \n 89  \nwww.lawcommission.gov.np \n•73A. Provisions relating to disadvantage, grievance  of civil \nemployees and handling thereof : (1) Except in cases where a \ncivil employee may file a complaint or appeal elsew here pursuant to \nthis Act and the prevailing law, if the civil emplo yee thinks that \nhe/she has suffered disadvantage in the service, co nditions and \nfacilities provided under this Act and the rules fr amed hereunder and \nin any matter concerning the employee or if no acti on has been \ntaken even after informing the concerned body about  the same, such \nemployee may present, as prescribed, the disadvanta ge and \ngrievance which he/she has suffered to the prescrib ed body.  \n(2) Other provisions relating to disadvantage, grie vance of \ncivil employees and handling thereof shall be as pr escribed. \n•73B Establishment and operation of employee welfare  fund : (1) \nThere may be established as prescribed a welfare fu nd for the \nwelfare of working civil employees, retired persons  and their family \nmembers. \n(2) The operation and management of the fund establ ished \npursuant to Sub-section (1) shall be as prescribed.  \n•73C. Provision relating to employee to Royal Palace  Service : (1) \nThe employee working in Royal Palace Service at the  time of \ncommencement of this Act, shall be administered and  managed by a \nseparate regulation. \n(2) The Royal Palace Service Act, 2029 and Rules ma de \nthereunder are hereby repealed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "Handing over charge : Any civil employee required to hand over", "content": "the cash, goods in kind or documents required to be  handed over by \n                                                   \n•  Inserted by the Second Amendment. \n \n \nwww.lawcommission.gov.np \n \n 90  \nwww.lawcommission.gov.np \nhim/her must hand them over to the concerned employ ee within the \nprescribed time-limit, and the person required to t ake them over \nmust take them over within that time-limit.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Power to frame rules : Government of Nepal may, in order to", "content": "implement the objectives of this Act, frame rules t o be generally \napplicable to all the civil services or to be sever ally applicable to \ndifferent services or groups.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "Repeal and saving : (1) The Civil Service Act, 2013 (1957) in", "content": "hereby repealed.  \n(2) All the acts done and actions taken pursuant to  the Civil \nService Act, 2013 (1957) and the rules framed there under shall be \ndeemed to have been done and taken under this Act. \n   \n \nNote: 1.  An Act made to Amend Some Nepal Laws, 206 3 has \nchanged the words \"His Majesty's Government into \n\"Government of Nepal\" instead of.\"", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Sections 64 and 65 of the Civil Service (Second", "content": "Amendment) Act, 2064 shall be as follows.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "To maintain ipso facto  in the changed service :", "content": "The service of the employees and officers working a nd \nbeing maintained in the Auditor General Office as p er \nSection 9 of the Audit Act, 2048 at the commencemen t of \nthis Act shall be ipso facto maintained in the serv ice \npursuant to Clause (e1) of Section 3 and those offi cers and \nemployees shall ipso facto  be changed in the same class.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Repeal and saving : (1) Section 9 of the Audit Act,", "content": "2048 has been repealed. \nwww.lawcommission.gov.np \n \n 91  \nwww.lawcommission.gov.np \n(2) All acts preformed or actions taken from the \n17 th  Aashad  of the year 2063 to the earlier date of the \ncommencement of this Act shall be deemed to have \nbeen performed or taken under this Act.  \n(3) The prevailing provisions before of 30 \nth  \nAashad of the year 2062 shall continue to apply until \nthe provisions relating to promotion on ground of w ork \nefficiency commence.", "children": []}]}]$CODEx752272698716$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
